import { useCallback, useRef, useState } from 'react';

const DEBOUNCE_DELAY = 300;

/**
 * Abstracts the debouncing logic
 *
 * @returns [value, debouncedValue, callbackToSetValue]
 * *
 * @example
 * ```
 * const [searchValue, query, handleSearch] = useDebouncedValue();
 *
 * useEffect(() => {
 *   const {data} = useDataQuery({query})
 * }, [query])
 *
 * return <InputSearch onChange={handleSearch} value={searchValue}/>
 * ```
 *
 */
export function useDebouncedValue(): [string, string, (v: string) => void] {
  const handle = useRef<NodeJS.Timeout>();

  const [value, setValue] = useState('');
  const [debouncedValue, setDebouncedValue] = useState('');

  const handleValueChange = useCallback((value: string) => {
    setValue(value);

    if (handle.current) {
      clearTimeout(handle.current);
    }

    handle.current = setTimeout(() => {
      setDebouncedValue(value);
    }, DEBOUNCE_DELAY);
  }, []);

  return [value, debouncedValue, handleValueChange];
}
